function translateUI(root=document.body){if(translatingUI||!root||typeof document.createTreeWalker!=='function')return;translatingUI=true;try{let en=state.language==='en';document.documentElement.lang=en?'en':'de';document.title=en?'PULS · Fitness tracker':'PULS · Fitness-Tracker';let walker=document.createTreeWalker(root,4),node;while(node=walker.nextNode()){if(protectedUIText(node.parentElement)||!node.nodeValue?.trim())continue;let record=uiTextOriginal.get(node);if(!record||node.nodeValue!==record.last)record={source:node.nodeValue,last:node.nodeValue};let next=en?translatedUI(record.source):record.source;if(node.nodeValue!==next)node.nodeValue=next;record.last=next;uiTextOriginal.set(node,record)}for(let el of root.querySelectorAll('[aria-label],[placeholder],[title]')){let records=uiAttrOriginal.get(el)||{};for(let attr of ['aria-label','placeholder','title']){let text=el.getAttribute(attr);if(!text)continue;let record=records[attr];if(!record||text!==record.last)record={source:text,last:text};let next=en?translatedUI(record.source):record.source;if(next!==text)el.setAttribute(attr,next);record.last=next;records[attr]=record}uiAttrOriginal.set(el,records)}}finally{translatingUI=false}}
